/* ================= the export the game's build reads (specs/ark_round.py) =================
   node ark_round_geometry.js [PC]  ->  JSON on stdout, in the artifact's frame (x the nose axis, y up):
     mats     the surface names (hull, panel, metal, trim, glass, engine, ...)
     motions  each turning part, once: {speed (radians a second about x through the origin)}
     polys    flat: [motion (-1 static), mat, n, x0, y0, z0, ... ] for every surface polygon
     prisms   every prism block: {tier, motion, c, a, b, d, h: [ha, hb, hd]} (a box centred c with half extents h along
              the orthonormal a, b, d), the danger spikes at the stern as their bounding blocks
     omni     where the omni crystal sits and its radius (the game puts its own crystal there)
     anchors  the page's named points (the booster's nozzles, the walkways, ...) */
if (typeof module !== "undefined" && require.main === module) {
  PC = Number(process.argv[2] || 1);
  // what only the page needs: the escort drawn for scale, and the rooms and people inside the closed decks
  escort = function () {};
  room = function () {};
  person = function () {};
  const TIER_MATS = { prism: 1, shield: 1, super: 1, danger: 1 };
  const motions = [], motionId = new Map(), prisms = [], omni = [];
  const mid = a => { if (!a) return -1; if (!motionId.has(a)) { motionId.set(a, motions.length); motions.push({ mode: a.mode, piv: a.piv, ax: a.ax, speed: a.speed }) } return motionId.get(a) };
  const box0 = Mesh.prototype.box, octa0 = Mesh.prototype.octa, omni0 = Mesh.prototype.omni;
  Mesh.prototype.box = function (c, a, b, d, ha, hb, hd, mat, tone) {
    if (TIER_MATS[mat]) { this.tally(mat); prisms.push({ tier: mat, motion: mid(this.a), c, a, b, d, h: [ha, hb, hd] }); return }
    return box0.call(this, c, a, b, d, ha, hb, hd, mat, tone);
  };
  Mesh.prototype.octa = function (c, a, b, d, sa, sb, sd, mat) {
    if (TIER_MATS[mat]) { this.tally(mat); prisms.push({ tier: mat, motion: mid(this.a), c, a, b, d, h: [sa, sb, sd], octa: true }); return }
    return octa0.call(this, c, a, b, d, sa, sb, sd, mat);
  };
  Mesh.prototype.omni = function (c, s, mat) {
    let r = 0; for (let i = 0; i < OMNI_V.length; i += 3) r = Math.max(r, Math.hypot(OMNI_V[i], OMNI_V[i + 1], OMNI_V[i + 2]));
    omni.push({ c, scale: s, radius: r * s });
  };
  const M = new Mesh();
  VARS.D.build(M);
  const mats = [], matId = {}, flat = [];
  const r6 = v => Math.round(v * 1e5) / 1e5;
  for (const o of M.p) {
    if (!(o.mat in matId)) { matId[o.mat] = mats.length; mats.push(o.mat) }
    flat.push(mid(o.a), matId[o.mat], o.pts.length);
    for (const p of o.pts) flat.push(r6(p[0]), r6(p[1]), r6(p[2]));
  }
  process.stdout.write(JSON.stringify({ pc: PC, mats, motions, polys: flat, prisms, omni, anchors: M.anchors, tally: M.cnt,
    consts: { RT, HULL_END, GAP_END, CX, STERN, MOUTH_R, XB, XJ, RB, JX0, JX1, JR, JC, MX0, MXF, WALK_R, POD_R, EXITS,
              BRANCH: BRANCH.map(b => ({ t: b.t, E: b.E, D: b.D, L: b.L })) } }));
}
